code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;

    long long total = 0;
    if (n > 1) {
        total = 1;
        for (long long d = 2; d * d <= n; d++) {
            if (n % d == 0) {
                total += d;
                if (d * d != n) {
                    total += n / d;
                }
            }
        }
    }
    cout << (total == n ? "yes" : "no") << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();

        long total = 0;
        if (n > 1) {
            total = 1;
            for (long d = 2; d * d <= n; d++) {
                if (n % d == 0) {
                    total += d;
                    if (d * d != n) {
                        total += n / d;
                    }
                }
            }
        }
        System.out.println(total == n ? "yes" : "no");
    }
}
